"use client"

import { useState, useEffect } from "react"
import { Bell, Search, Menu } from "lucide-react"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"

export function Navbar() {
  const [avatar, setAvatar] = useState("https://api.dicebear.com/7.x/avataaars/svg?seed=Berkay")

  // Sayfa yüklendiğinde ve localStorage değiştiğinde resmi güncelle
  useEffect(() => {
    const updateAvatar = () => {
      const savedAvatar = localStorage.getItem("user_avatar")
      if (savedAvatar) {
        setAvatar(savedAvatar)
      }
    }

    updateAvatar()

    // Diğer sayfalardan yapılan değişiklikleri dinlemek için event listener
    window.addEventListener("storage", updateAvatar)
    
    // Aynı sekme içindeki güncellemeler için özel bir event
    window.addEventListener("avatarChanged", updateAvatar as EventListener)

    return () => {
      window.removeEventListener("storage", updateAvatar)
      window.removeEventListener("avatarChanged", updateAvatar as EventListener)
    }
  }, [])

  return (
    <header className="sticky top-0 z-30 flex h-16 w-full items-center justify-between border-b bg-background/95 px-6 backdrop-blur supports-[backdrop-filter]:bg-background/60">
      <div className="flex items-center gap-4 flex-1 max-w-md">
        <Button variant="ghost" size="icon" className="md:hidden">
          <Menu className="h-5 w-5" />
        </Button>
        <div className="relative w-full">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            type="search"
            placeholder="Ara..."
            className="w-full bg-muted/50 pl-8 md:w-[300px] lg:w-[330px] rounded-lg"
          />
        </div>
      </div>

      <div className="flex items-center gap-4">
        <Button variant="ghost" size="icon" className="relative rounded-full">
          <Bell className="h-5 w-5" />
          <span className="absolute top-1.5 right-1.5 h-2 w-2 rounded-full bg-primary" />
        </Button>

        <div className="flex items-center gap-3 pl-2 border-l">
          <Avatar className="h-9 w-9 border">
            <AvatarImage src={avatar} alt="Berkay Kök" />
            <AvatarFallback>BK</AvatarFallback>
          </Avatar>
          <div className="hidden lg:flex flex-col text-left">
            <span className="text-sm font-semibold leading-none">Berkay Kök</span>
            <span className="text-xs text-muted-foreground mt-1">Admin</span>
          </div>
        </div>
      </div>
    </header>
  )
}